$gpus = Get-CimInstance Win32_VideoController | Where-Object { $_.PNPDeviceID -like 'PCI\VEN_10DE*' }
foreach ($g in $gpus) {
    $enumKey = "HKLM:\SYSTEM\ControlSet001\Enum\$($g.PNPDeviceID)"
    try {
        $driver = (Get-ItemProperty -Path $enumKey -Name 'Driver' -ErrorAction Stop).Driver
        $classKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\$driver"
        New-ItemProperty -Path $classKey -Name 'DisableAsyncPstates' -PropertyType DWord -Value 1 -Force 
        New-ItemProperty -Path $classKey -Name 'DisableDynamicPstate' -PropertyType DWord -Value 1 -Force 
    } catch { }
}

